// ---------------------------------------------------------------- mock provider server

#[derive(Debug, Clone)]
struct Call {
    url: String,
    method: String,
    headers: HashMap<String, String>,
    body: Value,
}

#[derive(Default)]
struct Resp {
    status: u16,
    json: Option<Value>,
    text: Option<String>,
    headers: Vec<(String, String)>,
}

fn ok(json: Value) -> Resp {
    Resp {
        status: 200,
        json: Some(json),
        ..Default::default()
    }
}
fn status(status: u16, json: Value) -> Resp {
    Resp {
        status,
        json: Some(json),
        ..Default::default()
    }
}
fn empty(status: u16) -> Resp {
    Resp {
        status,
        text: Some(String::new()),
        ..Default::default()
    }
}

type Handler = Box<dyn Fn(&Call) -> Resp + Send + Sync>;

struct Inner {
    routes: Vec<(Regex, Handler)>,
    calls: Mutex<Vec<Call>>,
}

struct Mock {
    inner: Arc<Inner>,
    http: Http,
}

impl Mock {
    fn calls(&self) -> Vec<Call> {
        self.inner.calls.lock().unwrap().clone()
    }
    fn find(&self, re: &str) -> Call {
        self.find_opt(re, None).unwrap_or_else(|| {
            panic!(
                "no call matching {re}: {:#?}",
                self.calls().iter().map(|c| &c.url).collect::<Vec<_>>()
            )
        })
    }
    fn find_opt(&self, re: &str, method: Option<&str>) -> Option<Call> {
        let re = Regex::new(re).unwrap();
        self.calls()
            .into_iter()
            .find(|c| re.is_match(&c.url) && method.is_none_or(|m| c.method == m))
    }
    fn matching(&self, re: &str) -> Vec<Call> {
        let re = Regex::new(re).unwrap();
        self.calls()
            .into_iter()
            .filter(|c| re.is_match(&c.url))
            .collect()
    }
    fn clear(&self) {
        self.inner.calls.lock().unwrap().clear();
    }
}

/// A route: regex matched against the ORIGINAL url (`https://host/path?query`), like the TS mock.
fn route(re: &str, f: impl Fn(&Call) -> Resp + Send + Sync + 'static) -> (Regex, Handler) {
    (Regex::new(re).unwrap(), Box::new(f))
}
/// `url.startsWith(prefix)` route.
fn prefix(p: &str, f: impl Fn(&Call) -> Resp + Send + Sync + 'static) -> (Regex, Handler) {
    route(&format!("^{}", regex::escape(p)), f)
}

fn test_env() -> HashMap<String, String> {
    let mut env = HashMap::new();
    for k in [
        "FACEBOOK",
        "LINKEDIN",
        "PINTEREST",
        "X",
        "YOUTUBE",
        "THREADS",
    ] {
        env.insert(
            format!("OC_{k}_CLIENT_ID"),
            format!("{}-id", k.to_lowercase()),
        );
        env.insert(
            format!("OC_{k}_CLIENT_SECRET"),
            format!("{}-secret", k.to_lowercase()),
        );
    }
    env.insert("OC_TIKTOK_CLIENT_KEY".into(), "tt-key".into());
    env.insert("OC_TIKTOK_CLIENT_SECRET".into(), "tt-secret".into());
    env
}

async fn mock(routes: Vec<(Regex, Handler)>) -> Mock {
    mock_env(routes, test_env()).await
}

async fn mock_env(routes: Vec<(Regex, Handler)>, env: HashMap<String, String>) -> Mock {
    let inner = Arc::new(Inner {
        routes,
        calls: Mutex::new(Vec::new()),
    });
    let app = Router::new().fallback(serve).with_state(inner.clone());
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });
    let base = format!("http://{addr}");
    let http = Http::with_env_map(env)
        .with_url_rewrite(move |u| {
            let rest = u
                .strip_prefix("https://")
                .or_else(|| u.strip_prefix("http://"))
                .unwrap_or(u);
            format!("{base}/{rest}")
        })
        .with_poll_interval(Duration::from_millis(1));
    Mock { inner, http }
}

async fn serve(State(inner): State<Arc<Inner>>, req: Request) -> Response {
    let (parts, body) = req.into_parts();
    let pq = parts
        .uri
        .path_and_query()
        .map(|p| p.as_str())
        .unwrap_or("/");
    let url = format!("https://{}", pq.trim_start_matches('/'));
    let mut headers = HashMap::new();
    for (k, v) in &parts.headers {
        headers.insert(k.as_str().to_string(), v.to_str().unwrap_or("").to_string());
    }
    let bytes = axum::body::to_bytes(body, usize::MAX).await.unwrap();
    let ctype = headers.get("content-type").cloned().unwrap_or_default();
    let body = decode_body(&bytes, &ctype);
    let call = Call {
        url: url.clone(),
        method: parts.method.to_string(),
        headers,
        body,
    };
    inner.calls.lock().unwrap().push(call.clone());
    let r = match inner.routes.iter().find(|(re, _)| re.is_match(&url)) {
        Some((_, f)) => f(&call),
        None => status(
            404,
            json!({ "error": { "message": format!("unmocked {url}") } }),
        ),
    };
    let text = r
        .text
        .unwrap_or_else(|| serde_json::to_string(&r.json.unwrap_or(json!({}))).unwrap());
    let mut b = Response::builder()
        .status(if r.status == 0 { 200 } else { r.status })
        .header("content-type", "application/json");
    for (k, v) in r.headers {
        b = b.header(k, v);
    }
    b.body(AxBody::from(text)).unwrap()
}

fn decode_body(bytes: &[u8], ctype: &str) -> Value {
    if bytes.is_empty() {
        return Value::Null;
    }
    if ctype.starts_with("application/json") || ctype.starts_with("text/plain") {
        let s = String::from_utf8_lossy(bytes).into_owned();
        return serde_json::from_str(&s).unwrap_or(Value::String(s));
    }
    if ctype.starts_with("application/x-www-form-urlencoded") {
        let mut m = Map::new();
        for (k, v) in url::form_urlencoded::parse(bytes) {
            m.insert(k.into_owned(), Value::String(v.into_owned()));
        }
        return Value::Object(m);
    }
    if let Some(boundary) = ctype.split("boundary=").nth(1) {
        return parse_multipart(bytes, boundary.trim_matches('"'));
    }
    Value::String(format!("<bytes {}>", bytes.len()))
}

fn parse_multipart(bytes: &[u8], boundary: &str) -> Value {
    let delim = format!("--{boundary}").into_bytes();
    let mut out = Map::new();
    let mut i = 0;
    let mut starts = Vec::new();
    while i + delim.len() <= bytes.len() {
        if bytes[i..].starts_with(&delim) {
            starts.push(i);
            i += delim.len();
        } else {
            i += 1;
        }
    }
    let name_re = Regex::new(r#"name="([^"]*)""#).unwrap();
    for w in starts.windows(2) {
        let part = &bytes[w[0] + delim.len()..w[1]];
        let part = part.strip_prefix(b"\r\n").unwrap_or(part);
        let part = part.strip_suffix(b"\r\n").unwrap_or(part);
        let Some(split) = part.windows(4).position(|x| x == b"\r\n\r\n") else {
            continue;
        };
        let head = String::from_utf8_lossy(&part[..split]).to_string();
        let content = &part[split + 4..];
        let name = name_re
            .captures(&head)
            .map(|c| c[1].to_string())
            .unwrap_or_default();
        let is_file = head.contains("filename=");
        let v = if is_file {
            format!("<file {}>", content.len())
        } else {
            String::from_utf8_lossy(content).into_owned()
        };
        out.insert(name, Value::String(v));
    }
    Value::Object(out)
}

/// `expect(actual).toMatchObject(expected)`.
fn assert_match(actual: &Value, expected: &Value) {
    fn matches(a: &Value, e: &Value) -> bool {
        match (a, e) {
            (Value::Object(a), Value::Object(e)) => e
                .iter()
                .all(|(k, ev)| a.get(k).is_some_and(|av| matches(av, ev))),
            (Value::Array(a), Value::Array(e)) => {
                a.len() == e.len() && a.iter().zip(e).all(|(x, y)| matches(x, y))
            }
            _ => a == e,
        }
    }
    assert!(
        matches(actual, expected),
        "expected {actual:#} to match {expected:#}"
    );
}

// ---------------------------------------------------------------- fixtures

fn file(i: usize, mime: &str) -> MediaFile {
    let d = i.to_string().repeat(64)[..64].to_string();
    MediaFile {
        bytes: vec![0; 1000 + i],
        mime: mime.into(),
        filename: format!("d-{i}.{}", if mime == "video/mp4" { "mp4" } else { "jpg" }),
        url: format!("https://cdn.example/api/social/media/{d}.jpg?exp=1&sig=s"),
        width: 1080.0,
        height: 1350.0,
    }
}
fn jpg(i: usize) -> MediaFile {
    file(i, "image/jpeg")
}
fn mp4() -> MediaFile {
    file(0, "video/mp4")
}

fn ctx() -> PublishContext {
    PublishContext {
        account: AccountInfo {
            external_id: "EXT".into(),
            display_name: "Acme".into(),
            handle: Some("acme".into()),
            meta: Map::new(),
        },
        tokens: Tokens {
            access_token: "TOKEN".into(),
            ..Default::default()
        },
        media: vec![jpg(0)],
        kind: PostKind::Image,
        text: "Hello #launch".into(),
        hashtags: vec!["launch".into()],
        options: Map::new(),
        title: "Spring sale".into(),
    }
}
fn carousel() -> PublishContext {
    PublishContext {
        media: vec![jpg(0), jpg(1)],
        kind: PostKind::Carousel,
        ..ctx()
    }
}
fn video() -> PublishContext {
    PublishContext {
        media: vec![mp4()],
        kind: PostKind::Video,
        ..ctx()
    }
}
fn opts(v: Value) -> Map<String, Value> {
    v.as_object().unwrap().clone()
}
fn counter() -> Arc<AtomicUsize> {
    Arc::new(AtomicUsize::new(0))
}

// ---------------------------------------------------------------- crypto

#[test]
fn token_encryption_round_trips_and_is_randomized() {
    let t = Tokens {
        access_token: "a.b.c".into(),
        refresh_token: Some("r".into()),
        expires_at: Some(123.0),
        extra: Some(
            [("appPassword".to_string(), "xxxx-xxxx".to_string())]
                .into_iter()
                .collect(),
        ),
    };
    let a = seal_tokens(&t, "secret-1");
    let b = seal_tokens(&t, "secret-1");
    assert_ne!(a, b);
    assert!(a.starts_with("v1."));
    assert!(!a.contains("a.b.c"));
    assert_eq!(open_tokens(&a, "secret-1").unwrap(), t);
    // JSON.stringify shape: integral expiresAt without a fraction.
    assert_eq!(
        decrypt(&a, "secret-1").unwrap(),
        r#"{"accessToken":"a.b.c","refreshToken":"r","expiresAt":123,"extra":{"appPassword":"xxxx-xxxx"}}"#
    );
}

#[test]
fn token_encryption_rejects_tampering_and_the_wrong_key() {
    use base64::Engine as _;
    let s = encrypt("hello", "k1");
    assert_eq!(decrypt(&s, "k1").unwrap(), "hello");
    assert!(matches!(decrypt(&s, "k2"), Err(TokenError::Auth)));
    let mut raw = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(&s[3..])
        .unwrap();
    *raw.last_mut().unwrap() ^= 1;
    let tampered = format!(
        "v1.{}",
        base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(&raw)
    );
    assert!(decrypt(&tampered, "k1").is_err());
    assert_eq!(
        decrypt("plain", "k1").unwrap_err().to_string(),
        "unknown token format"
    );
    assert_eq!(
        decrypt("v1.AAAA", "k1").unwrap_err().to_string(),
        "token ciphertext too short"
    );
}

#[test]
fn signs_media_links_with_expiry() {
    let secret = "media-secret";
    let sha = "a".repeat(64);
    let now = oc_js::now_ms() as f64;
    let exp = (now / 1000.0).floor() + 60.0;
    assert!(verify_media_sig(
        &sha,
        exp,
        &media_sig(&sha, exp, secret),
        now,
        secret
    ));
    assert!(!verify_media_sig(
        &"b".repeat(64),
        exp,
        &media_sig(&sha, exp, secret),
        now,
        secret
    ));
    assert!(!verify_media_sig(
        &sha,
        exp - 120.0,
        &media_sig(&sha, exp - 120.0, secret),
        now,
        secret
    ));
    assert!(!verify_media_sig(&sha, f64::NAN, "x", now, secret));
    let u = url::Url::parse(&signed_media_url(
        &sha,
        "png",
        60,
        "https://u.example",
        secret,
    ))
    .unwrap();
    assert_eq!(u.path(), format!("/api/social/media/{sha}.png"));
    let q: HashMap<String, String> = u.query_pairs().into_owned().collect();
    assert!(verify_media_sig(
        &sha,
        q["exp"].parse().unwrap(),
        &q["sig"],
        now,
        secret
    ));
}

// ---------------------------------------------------------------- text helpers

#[test]
fn appends_hashtags_not_already_in_the_caption() {
    let tags = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
    assert_eq!(
        compose_text("Big news #launch", &tags(&["launch", "#spring", "sale"])),
        "Big news #launch\n\n#spring #sale"
    );
    assert_eq!(compose_text("", &tags(&["a"])), "#a");
    assert_eq!(
        compose_text("#launchday", &tags(&["launch"])),
        "#launchday\n\n#launch"
    );
}

#[test]
fn counts_graphemes_and_x_url_weight() {
    assert_eq!(char_count("👍🏽ok", None), 3);
    assert_eq!(
        char_count(
            "see https://example.com/a/very/long/path/indeed/yes",
            Some("x")
        ),
        4 + 23
    );
}

