#[test]
fn is_not_configured_without_client_credentials() {
    let mut env = test_env();
    env.remove("OC_LINKEDIN_CLIENT_SECRET");
    env.insert("OC_YOUTUBE_CLIENT_ID".into(), "   ".into());
    let http = Http::with_env_map(env.clone());
    assert!(!LINKEDIN.configured(&http));
    assert!(!YOUTUBE.configured(&http));
    assert!(XCOM.configured(&http));
    assert!(BLUESKY.configured(&http));
    env.insert("OC_BLUESKY_DISABLED".into(), " 1 ".into());
    assert!(!BLUESKY.configured(&Http::with_env_map(env)));
}

#[test]
fn env_is_trimmed_and_blank_is_unset() {
    let http = Http::with_env(|n| match n {
        "A" => Some("  v  ".into()),
        "B" => Some(" \t\n".into()),
        _ => None,
    });
    assert_eq!(http.env("A").as_deref(), Some("v"));
    assert_eq!(http.env("B"), None);
    assert_eq!(http.env("C"), None);
}

// ---------------------------------------------------------------- publish request shapes

#[tokio::test]
async fn facebook_single_photo_and_multi_photo_feed_post() {
    let n = counter();
    let n2 = n.clone();
    let m = mock(vec![
        route(r"/EXT/photos", move |_| ok(json!({ "id": format!("PH{}", n2.fetch_add(1, Ordering::SeqCst) + 1), "post_id": "EXT_99" }))),
        route(r"/EXT/feed", |_| ok(json!({ "id": "EXT_100" }))),
    ])
    .await;
    let r = FACEBOOK.publish(&m.http, &ctx()).await.unwrap();
    assert_eq!(r.url.as_deref(), Some("https://www.facebook.com/EXT_99"));
    assert_eq!(r.external_id.as_deref(), Some("EXT_99"));
    let c0 = &m.calls()[0];
    assert!(
        c0.url
            .starts_with("https://graph.facebook.com/v23.0/EXT/photos")
    );
    assert_eq!(c0.method, "POST");
    assert_match(
        &c0.body,
        &json!({ "url": jpg(0).url, "message": "Hello #launch", "published": "true" }),
    );
    assert_eq!(c0.headers["authorization"], "Bearer TOKEN");
    assert_eq!(c0.headers["user-agent"], "Pinselo/1.0 (+self-hosted)");
    assert_eq!(c0.headers["accept"], "application/json");
    assert_eq!(
        c0.headers["content-type"],
        "application/x-www-form-urlencoded"
    );
    m.clear();
    let r = FACEBOOK.publish(&m.http, &carousel()).await.unwrap();
    assert_eq!(r.url.as_deref(), Some("https://www.facebook.com/EXT_100"));
    let feed = m.find(r"/feed");
    assert_match(
        &feed.body,
        &json!({ "message": "Hello #launch", "attached_media[0]": "{\"media_fbid\":\"PH2\"}", "attached_media[1]": "{\"media_fbid\":\"PH3\"}" }),
    );
    assert!(
        m.matching("photos")
            .iter()
            .all(|c| c.body["published"] == "false")
    );
}

