#[tokio::test]
async fn instagram_carousel_containers_then_media_publish() {
    let n = counter();
    let n2 = n.clone();
    let m = mock(vec![
        route(r"/EXT/media_publish", |_| ok(json!({ "id": "M1" }))),
        route(r"/EXT/media$", move |_| {
            ok(json!({ "id": format!("C{}", n2.fetch_add(1, Ordering::SeqCst) + 1) }))
        }),
        route(r"/C\d\?fields=status_code", |_| {
            ok(json!({ "status_code": "FINISHED" }))
        }),
        route(r"/M1\?fields=permalink", |_| {
            ok(json!({ "permalink": "https://www.instagram.com/p/abc/" }))
        }),
    ])
    .await;
    let r = INSTAGRAM.publish(&m.http, &carousel()).await.unwrap();
    let media = m.matching(r"/media$");
    assert_match(
        &media[0].body,
        &json!({ "image_url": jpg(0).url, "is_carousel_item": "true" }),
    );
    assert_match(
        &media[2].body,
        &json!({ "media_type": "CAROUSEL", "children": "C1,C2", "caption": "Hello #launch" }),
    );
    assert_eq!(m.find("media_publish").body, json!({ "creation_id": "C3" }));
    assert_eq!(
        m.find(r"/C3\?").url,
        "https://graph.facebook.com/v23.0/C3?fields=status_code%2Cstatus"
    );
    assert_eq!(r.url.as_deref(), Some("https://www.instagram.com/p/abc/"));
    assert_eq!(r.external_id.as_deref(), Some("M1"));
}

#[tokio::test]
async fn instagram_reels_wait_for_processing() {
    let polls = counter();
    let p2 = polls.clone();
    let m = mock(vec![
        route(r"/EXT/media_publish", |_| ok(json!({ "id": "M2" }))),
        route(r"/EXT/media$", |_| ok(json!({ "id": "R1" }))),
        route(r"/R1\?fields=status_code", move |_| {
            let n = p2.fetch_add(1, Ordering::SeqCst) + 1;
            ok(json!({ "status_code": if n < 2 { "IN_PROGRESS" } else { "FINISHED" } }))
        }),
        route(r"/M2\?fields=permalink", |_| {
            ok(json!({ "permalink": "https://www.instagram.com/reel/x/" }))
        }),
    ])
    .await;
    let r = INSTAGRAM.publish(&m.http, &video()).await.unwrap();
    assert_eq!(r.url.as_deref(), Some("https://www.instagram.com/reel/x/"));
    assert_match(
        &m.find(r"/media$").body,
        &json!({ "media_type": "REELS", "video_url": mp4().url, "caption": "Hello #launch", "share_to_feed": "true" }),
    );
    assert_eq!(polls.load(Ordering::SeqCst), 2);
}

#[tokio::test]
async fn instagram_processing_error_is_permanent_and_missing_permalink_is_null() {
    let m = mock(vec![
        route(r"/EXT/media$", |_| ok(json!({ "id": "R1" }))),
        route(r"/R1\?fields=status_code", |_| {
            ok(json!({ "status_code": "ERROR", "status": "Error: bad codec" }))
        }),
    ])
    .await;
    let e = INSTAGRAM.publish(&m.http, &video()).await.unwrap_err();
    assert_eq!(
        e.message,
        "Instagram could not process the media (Error: bad codec)"
    );
    assert!(!e.transient);

    let m = mock(vec![
        route(r"/EXT/media_publish", |_| ok(json!({ "id": "M3" }))),
        route(r"/EXT/media$", |_| ok(json!({ "id": "I1" }))),
    ])
    .await;
    let r = INSTAGRAM.publish(&m.http, &ctx()).await.unwrap();
    // The permalink lookup 404s (unmocked) → url null, but the post succeeded.
    assert_eq!(r.url, None);
    assert_eq!(r.external_id.as_deref(), Some("M3"));
    assert!(
        m.find_opt(r"/I1\?fields", None).is_none(),
        "single images do not poll"
    );
}

#[tokio::test]
async fn linkedin_image_upload_then_versioned_post() {
    let m = mock(vec![
        route(r"rest/images\?action=initializeUpload", |_| {
            ok(json!({ "value": { "uploadUrl": "https://www.linkedin.com/dms-uploads/abc", "image": "urn:li:image:I1" } }))
        }),
        prefix("https://www.linkedin.com/dms-uploads/abc", |_| empty(201)),
        route(r"rest/posts", |_| Resp { status: 201, text: Some(String::new()), headers: vec![("x-restli-id".into(), "urn:li:share:7".into())], ..Default::default() }),
    ])
    .await;
    let r = LINKEDIN.publish(&m.http, &ctx()).await.unwrap();
    assert_eq!(
        m.find("initializeUpload").body,
        json!({ "initializeUploadRequest": { "owner": "urn:li:person:EXT" } })
    );
    let post = m.find(r"rest/posts");
    assert!(
        Regex::new(r"^\d{6}$")
            .unwrap()
            .is_match(&post.headers["linkedin-version"])
    );
    assert_eq!(post.headers["x-restli-protocol-version"], "2.0.0");
    assert_match(
        &post.body,
        &json!({
            "author": "urn:li:person:EXT", "commentary": "Hello {hashtag|\\#|launch}", "visibility": "PUBLIC", "lifecycleState": "PUBLISHED",
            "distribution": { "feedDistribution": "MAIN_FEED" }, "content": { "media": { "id": "urn:li:image:I1", "altText": "Spring sale" } },
        }),
    );
    let put = m.find_opt("dms-uploads", Some("PUT")).expect("PUT upload");
    assert_eq!(put.body, json!("<bytes 1000>"));
    assert_eq!(put.headers["content-type"], "image/jpeg");
    assert_eq!(
        r.url.as_deref(),
        Some("https://www.linkedin.com/feed/update/urn:li:share:7/")
    );
}

