#[tokio::test]
async fn linkedin_refresh_keeps_the_old_refresh_token() {
    let m = mock(vec![prefix(
        "https://www.linkedin.com/oauth/v2/accessToken",
        |_| ok(json!({ "access_token": "NEW", "expires_in": 3600 })),
    )])
    .await;
    let t = Tokens {
        access_token: "OLD".into(),
        refresh_token: Some("RT".into()),
        ..Default::default()
    };
    let next = LINKEDIN.refresh(&m.http, &t).await.unwrap().unwrap();
    assert_eq!(next.access_token, "NEW");
    assert_eq!(next.refresh_token.as_deref(), Some("RT"));
    assert!(next.expires_at.unwrap() > oc_js::now_ms() as f64);
    assert_eq!(
        m.calls()[0].body,
        json!({ "grant_type": "refresh_token", "refresh_token": "RT", "client_id": "linkedin-id", "client_secret": "linkedin-secret" })
    );
    assert!(LINKEDIN.has_refresh());
    assert_eq!(
        LINKEDIN
            .refresh(
                &m.http,
                &Tokens {
                    access_token: "A".into(),
                    ..Default::default()
                }
            )
            .await
            .unwrap(),
        None
    );
}

#[tokio::test]
async fn pinterest_image_pin_on_the_chosen_board() {
    let m = mock(vec![route(r"/v5/pins", |_| {
        status(201, json!({ "id": "555" }))
    })])
    .await;
    let c = PublishContext {
        account: AccountInfo {
            external_id: "acme".into(),
            display_name: "Acme".into(),
            handle: None,
            meta: opts(json!({ "boards": [{ "id": "B1" }] })),
        },
        options: opts(json!({ "pinterestBoardId": "B9", "link": "javascript:alert(1)" })),
        ..ctx()
    };
    let r = PINTEREST.publish(&m.http, &c).await.unwrap();
    let body = &m.calls()[0].body;
    assert_match(
        body,
        &json!({ "board_id": "B9", "title": "Spring sale", "description": "Hello #launch", "media_source": { "source_type": "image_url", "url": jpg(0).url } }),
    );
    assert!(body.get("link").is_none());
    assert_eq!(r.url.as_deref(), Some("https://www.pinterest.com/pin/555/"));
    let e = PINTEREST.publish(&m.http, &ctx()).await.unwrap_err();
    assert!(e.message.contains("board"), "{}", e.message);
    // First board fallback + carousel + http link.
    m.clear();
    let c = PublishContext {
        account: AccountInfo {
            meta: opts(json!({ "boards": [{ "id": "B1" }] })),
            ..ctx().account
        },
        options: opts(json!({ "link": "https://acme.example/sale" })),
        ..carousel()
    };
    PINTEREST.publish(&m.http, &c).await.unwrap();
    assert_match(
        &m.calls()[0].body,
        &json!({ "board_id": "B1", "link": "https://acme.example/sale", "media_source": { "source_type": "multiple_image_urls", "items": [
            { "url": jpg(0).url, "title": "Spring sale" }, { "url": jpg(1).url, "title": "Spring sale" }
        ] } }),
    );
}

