#[tokio::test]
async fn youtube_resumable_upload_short_for_vertical() {
    let m = mock(vec![
        route(r"upload/youtube/v3/videos\?uploadType=resumable", |_| {
            Resp {
                status: 200,
                text: Some(String::new()),
                headers: vec![(
                    "location".into(),
                    "https://www.googleapis.com/upload/youtube/v3/videos?upload_id=U1".into(),
                )],
                ..Default::default()
            }
        }),
        route(r"upload_id=U1", |_| ok(json!({ "id": "YT1" }))),
    ])
    .await;
    let c = PublishContext {
        media: vec![MediaFile {
            width: 1080.0,
            height: 1920.0,
            ..mp4()
        }],
        options: opts(json!({ "durationMs": 30_000 })),
        ..video()
    };
    let r = YOUTUBE.publish(&m.http, &c).await.unwrap();
    let init = &m.calls()[0];
    assert_eq!(
        init.url,
        "https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet%2Cstatus"
    );
    assert_eq!(init.headers["x-upload-content-length"], "1000");
    assert_eq!(init.headers["x-upload-content-type"], "video/mp4");
    assert_match(
        &init.body,
        &json!({ "snippet": { "title": "Hello #launch", "tags": ["launch"], "categoryId": "22" }, "status": { "privacyStatus": "public", "selfDeclaredMadeForKids": false } }),
    );
    assert_eq!(m.calls()[1].method, "PUT");
    assert_eq!(r.url.as_deref(), Some("https://www.youtube.com/shorts/YT1"));
    let e = YOUTUBE.publish(&m.http, &ctx()).await.unwrap_err();
    assert_eq!(
        e.message,
        "YouTube only accepts videos — schedule this design as MP4."
    );
    // Landscape → watch URL; custom title / privacy.
    m.clear();
    let c = PublishContext {
        options: opts(json!({ "youtubeTitle": "<b>Launch</b>", "youtubePrivacy": "unlisted" })),
        media: vec![MediaFile {
            width: 1920.0,
            height: 1080.0,
            ..mp4()
        }],
        ..video()
    };
    let r = YOUTUBE.publish(&m.http, &c).await.unwrap();
    assert_match(
        &m.calls()[0].body,
        &json!({ "snippet": { "title": "bLaunch/b" }, "status": { "privacyStatus": "unlisted" } }),
    );
    assert_eq!(
        r.url.as_deref(),
        Some("https://www.youtube.com/watch?v=YT1")
    );
}

