fn bsky_tokens() -> Tokens {
    let extra = [
        ("identifier", "acme.bsky.social"),
        ("appPassword", "abcd-efgh-ijkl-mnop"),
        ("pds", "https://pds.example"),
        ("did", "did:plc:abc"),
    ];
    Tokens {
        access_token: "A".into(),
        refresh_token: Some("R".into()),
        expires_at: None,
        extra: Some(
            extra
                .into_iter()
                .map(|(k, v)| (k.to_string(), v.to_string()))
                .collect(),
        ),
    }
}

