async fn bluesky_blob_upload_and_post_record() {
    let m = mock(vec![
        route(r"uploadBlob", |_| ok(json!({ "blob": { "$type": "blob", "ref": { "$link": "bafy" }, "mimeType": "image/jpeg", "size": 1000 } }))),
        route(r"createRecord", |_| ok(json!({ "uri": "at://did:plc:abc/app.bsky.feed.post/3kxyz", "cid": "c" }))),
    ])
    .await;
    let c = PublishContext {
        account: AccountInfo {
            external_id: "did:plc:abc".into(),
            display_name: "Acme".into(),
            handle: Some("acme.bsky.social".into()),
            meta: Map::new(),
        },
        tokens: bsky_tokens(),
        ..ctx()
    };
    let r = BLUESKY.publish(&m.http, &c).await.unwrap();
    let up = m.find("uploadBlob");
    assert_eq!(
        up.url,
        "https://pds.example/xrpc/com.atproto.repo.uploadBlob"
    );
    assert_eq!(up.headers["content-type"], "image/jpeg");
    assert_eq!(up.headers["authorization"], "Bearer A");
    let rec = m.find("createRecord").body;
    assert_eq!(rec["repo"], "did:plc:abc");
    assert_eq!(rec["collection"], "app.bsky.feed.post");
    assert_match(
        &rec["record"],
        &json!({
            "$type": "app.bsky.feed.post", "text": "Hello #launch",
            "facets": [{ "index": { "byteStart": 6, "byteEnd": 13 }, "features": [{ "$type": "app.bsky.richtext.facet#tag", "tag": "launch" }] }],
            "embed": { "$type": "app.bsky.embed.images", "images": [{ "alt": "Spring sale", "image": { "$type": "blob" }, "aspectRatio": { "width": 1080, "height": 1350 } }] },
        }),
    );
    let created = rec["record"]["createdAt"].as_str().unwrap();
    assert!(
        Regex::new(r"^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$")
            .unwrap()
            .is_match(created),
        "{created}"
    );
    assert_eq!(
        r.url.as_deref(),
        Some("https://bsky.app/profile/acme.bsky.social/post/3kxyz")
    );
    assert_eq!(
        r.external_id.as_deref(),
        Some("at://did:plc:abc/app.bsky.feed.post/3kxyz")
    );

    let e = BLUESKY.publish(&m.http, &video()).await.unwrap_err();
    assert_eq!(
        e.message,
        "Bluesky posts from Pinselo support images only — schedule this design as PNG or JPG."
    );
    let big = PublishContext {
        media: vec![MediaFile {
            bytes: vec![0; 1_000_001],
            ..jpg(0)
        }],
        ..c
    };
    assert_eq!(
        BLUESKY.publish(&m.http, &big).await.unwrap_err().message,
        "Bluesky images must be under 1 MB — choose JPG or fewer details."
    );
}

#[tokio::test]
async fn bluesky_refresh_falls_back_to_a_new_session() {
    let mut env = test_env();
    env.insert("OC_BLUESKY_SERVICE".into(), "https://entry.example/".into());
    let m = mock_env(
        vec![
            route(r"refreshSession", |_| status(400, json!({ "error": "ExpiredToken", "message": "Token has expired" }))),
            route(r"createSession", |_| {
                ok(json!({ "did": "did:plc:abc", "handle": "acme.bsky.social", "accessJwt": "A2", "refreshJwt": "R2",
                    "didDoc": { "service": [{ "id": "#atproto_pds", "type": "AtprotoPersonalDataServer", "serviceEndpoint": "https://pds2.example/" }] } }))
            }),
        ],
        env,
    )
    .await;
    let t = BLUESKY
        .refresh(&m.http, &bsky_tokens())
        .await
        .unwrap()
        .unwrap();
    assert_eq!(
        m.find("refreshSession").url,
        "https://pds.example/xrpc/com.atproto.server.refreshSession"
    );
    assert_eq!(
        m.find("refreshSession").headers["authorization"],
        "Bearer R"
    );
    let cs = m.find("createSession");
    assert_eq!(
        cs.url,
        "https://entry.example/xrpc/com.atproto.server.createSession"
    );
    assert_eq!(
        cs.body,
        json!({ "identifier": "acme.bsky.social", "password": "abcd-efgh-ijkl-mnop" })
    );
    assert_eq!(t.access_token, "A2");
    assert_eq!(t.refresh_token.as_deref(), Some("R2"));
    let extra = t.extra.unwrap();
    assert_eq!(extra["pds"], "https://pds2.example");
    assert_eq!(extra["did"], "did:plc:abc");
    // Without a stored app password there is nothing to fall back to.
    let bare = Tokens {
        extra: None,
        ..bsky_tokens()
    };
    assert_eq!(BLUESKY.refresh(&m.http, &bare).await.unwrap(), None);
}

