#[tokio::test]
async fn classifies_errors_as_transient_or_permanent() {
    let m = mock(vec![route(r"/EXT/photos", |_| {
        status(503, json!({ "error": { "message": "busy" } }))
    })])
    .await;
    let e = FACEBOOK.publish(&m.http, &ctx()).await.unwrap_err();
    assert_eq!(
        (e.transient, e.status, e.message.as_str(), e.reauth),
        (true, Some(503), "busy", false)
    );
    let m = mock(vec![route(r"/EXT/photos", |_| {
        status(400, json!({ "error": { "message": "(#100) bad url" } }))
    })])
    .await;
    let e = FACEBOOK.publish(&m.http, &ctx()).await.unwrap_err();
    assert_eq!((e.transient, e.message.as_str()), (false, "(#100) bad url"));
    let m = mock(vec![route(r"/EXT/photos", |_| {
        status(401, json!({ "error": { "message": "expired" } }))
    })])
    .await;
    let e = FACEBOOK.publish(&m.http, &ctx()).await.unwrap_err();
    assert_eq!((e.status, e.reauth), (Some(401), true));
}

#[tokio::test]
async fn network_failures_and_poll_timeouts_are_transient() {
    // Nothing listens on port 9 of a closed local socket.
    let http = Http::with_env(|_| None).with_url_rewrite(|_| "http://127.0.0.1:9/".into());
    let e = http
        .call("https://graph.facebook.com/x", Req::get())
        .await
        .unwrap_err();
    assert!(
        e.transient && e.message.starts_with("Network error: "),
        "{e:?}"
    );

    let m = mock(vec![
        route(r"/R1\?fields=status_code", |_| {
            ok(json!({ "status_code": "IN_PROGRESS" }))
        }),
        route(r"/EXT/media$", |_| ok(json!({ "id": "R1" }))),
    ])
    .await;
    let http = m.http.clone().with_poll_timeout(Duration::from_millis(20));
    let e = INSTAGRAM.publish(&http, &video()).await.unwrap_err();
    assert_eq!(
        e,
        PublishError::transient("Timed out waiting for Instagram to process the media")
    );
}

#[tokio::test]
async fn call_parses_json_or_text_bodies() {
    let m = mock(vec![
        prefix("https://t.example/json-as-text", |_| Resp {
            status: 200,
            text: Some(" {\"a\":1}".into()),
            headers: vec![("content-type".into(), "text/plain".into())],
            ..Default::default()
        }),
        prefix("https://t.example/text", |_| Resp {
            status: 200,
            text: Some("plain words".into()),
            headers: vec![("content-type".into(), "text/plain".into())],
            ..Default::default()
        }),
        prefix("https://t.example/bad-json", |_| Resp {
            status: 200,
            text: Some("{nope".into()),
            ..Default::default()
        }),
        prefix("https://t.example/err-text", |_| Resp {
            status: 502,
            text: Some("Bad Gateway".into()),
            headers: vec![("content-type".into(), "text/html".into())],
            ..Default::default()
        }),
        prefix("https://t.example/err-empty", |_| Resp {
            status: 429,
            text: Some(String::new()),
            ..Default::default()
        }),
    ])
    .await;
    assert_eq!(
        m.http
            .call("https://t.example/json-as-text", Req::get())
            .await
            .unwrap()
            .body,
        json!({ "a": 1 })
    );
    assert_eq!(
        m.http
            .call("https://t.example/text", Req::get())
            .await
            .unwrap()
            .body,
        json!("plain words")
    );
    assert_eq!(
        m.http
            .call("https://t.example/bad-json", Req::get())
            .await
            .unwrap()
            .body,
        json!("{nope")
    );
    let e = m
        .http
        .call("https://t.example/err-text", Req::get())
        .await
        .unwrap_err();
    assert_eq!(
        (e.message.as_str(), e.transient, e.status),
        ("Bad Gateway", true, Some(502))
    );
    let e = m
        .http
        .call("https://t.example/err-empty", Req::get())
        .await
        .unwrap_err();
    assert_eq!((e.message.as_str(), e.transient), ("HTTP 429", true));
}

#[test]
fn error_text_rules() {
    let t = |v: Value| h::error_text(&v, 400);
    assert_eq!(t(json!({ "error": { "message": "m", "code": 1 } })), "m");
    assert_eq!(t(json!({ "error": { "error_user_msg": "u" } })), "u");
    assert_eq!(t(json!({ "error": { "code": 190 } })), "190");
    assert_eq!(
        t(json!({ "error": { "type": "OAuthException" } })),
        r#"{"type":"OAuthException"}"#
    );
    assert_eq!(
        t(json!({ "error": "invalid_grant", "error_description": "Bad code" })),
        "Bad code"
    );
    assert_eq!(
        t(json!({ "error": "invalid_grant", "message": "msg" })),
        "msg"
    );
    assert_eq!(t(json!({ "error": "invalid_grant" })), "invalid_grant");
    assert_eq!(t(json!({ "message": "top" })), "top");
    assert_eq!(t(json!({ "detail": "Forbidden" })), "Forbidden");
    assert_eq!(t(json!({ "errors": [{ "message": "first" }] })), "first");
    assert_eq!(t(json!({ "errors": [{ "code": 1.0 }] })), r#"{"code":1}"#);
    assert_eq!(t(json!({ "message": "" })), "HTTP 400");
    assert_eq!(t(json!("x".repeat(400))), "x".repeat(300));
    assert_eq!(t(json!("")), "HTTP 400");
    assert_eq!(t(json!([1, 2])), "HTTP 400");
}

// ---------------------------------------------------------------- connect flows (OAuth, app password)

fn query_of(u: &str) -> HashMap<String, String> {
    url::Url::parse(u).unwrap().query_pairs().into_owned().collect()
}

fn ap(state: &str, redirect: &str, challenge: &str) -> AuthorizeParams {
    AuthorizeParams {
        state: state.into(),
        redirect_uri: redirect.into(),
        code_challenge: challenge.into(),
    }
}

fn xp(code: &str, redirect: &str, verifier: &str) -> ExchangeParams {
    ExchangeParams {
        code: code.into(),
        redirect_uri: redirect.into(),
        code_verifier: verifier.into(),
    }
}

#[test]
fn uses_pkce_s256_for_x_and_youtube() {
    let http = Http::with_env_map(test_env());
    let challenge = h::pkce_challenge("verifier-123");
    for a in [&XCOM as &dyn SocialAdapter, &YOUTUBE] {
        let q = query_of(&a.authorize_url(&http, &ap("st", "https://app/cb", &challenge)).unwrap());
        assert_eq!(q["code_challenge"], challenge);
        assert_eq!(q["code_challenge_method"], "S256");
        assert_eq!(q["state"], "st");
        assert_eq!(q["redirect_uri"], "https://app/cb");
    }
    let p = ap("s", "r", "c");
    assert_eq!(query_of(&YOUTUBE.authorize_url(&http, &p).unwrap())["access_type"], "offline");
    assert_eq!(query_of(&TIKTOK.authorize_url(&http, &p).unwrap())["client_key"], "tt-key");
    assert!(query_of(&FACEBOOK.authorize_url(&http, &p).unwrap())["scope"].contains("pages_manage_posts"));
    assert!(query_of(&INSTAGRAM.authorize_url(&http, &p).unwrap())["scope"].contains("instagram_content_publish"));
    // No OAuth for the built-in target and Bluesky (app password).
    assert!(LOCAL.authorize_url(&http, &p).is_none() && BLUESKY.authorize_url(&http, &p).is_none());
    assert!(LOCAL.exchange(&http, &xp("c", "r", "v")).is_none());
    assert!(BLUESKY.exchange(&http, &xp("c", "r", "v")).is_none());
    assert!(XCOM.connect_with_password(&http, "a", "b").is_none());
    // A fresh PKCE pair: 48 random bytes as base64url, S256 challenge.
    let (verifier, challenge) = h::pkce_pair();
    assert_eq!(verifier.len(), 64);
    assert_eq!(challenge, h::pkce_challenge(&verifier));
    assert_ne!(h::pkce_pair().0, verifier);
}

