#[tokio::test]
async fn exchanges_x_codes_with_the_verifier_and_basic_auth() {
    let m = mock(vec![
        prefix("https://api.x.com/2/oauth2/token", |_| {
            ok(json!({ "access_token": "AT", "refresh_token": "RT", "expires_in": 7200 }))
        }),
        prefix("https://api.x.com/2/users/me", |_| {
            ok(json!({ "data": { "id": "42", "name": "Acme", "username": "acme", "profile_image_url": "https://pbs/x.jpg" } }))
        }),
    ])
    .await;
    let before = oc_js::now_ms() as f64;
    let accts = XCOM.exchange(&m.http, &xp("C", "https://app/cb", "V")).unwrap().await.unwrap();
    let tok = m.find("oauth2/token");
    assert_match(
        &tok.body,
        &json!({ "grant_type": "authorization_code", "code": "C", "code_verifier": "V", "redirect_uri": "https://app/cb", "client_id": "x-id" }),
    );
    assert_eq!(tok.headers["authorization"], "Basic eC1pZDp4LXNlY3JldA==");
    let me = m.find("users/me");
    assert_eq!(me.url, "https://api.x.com/2/users/me?user.fields=profile_image_url");
    assert_eq!(me.headers["authorization"], "Bearer AT");
    assert_eq!(accts.len(), 1);
    let a = &accts[0];
    assert_eq!((a.external_id.as_str(), a.display_name.as_str()), ("42", "Acme"));
    assert_eq!(a.handle.as_deref(), Some("acme"));
    assert_eq!(a.avatar_url.as_deref(), Some("https://pbs/x.jpg"));
    assert_eq!(a.tokens.access_token, "AT");
    assert_eq!(a.tokens.refresh_token.as_deref(), Some("RT"));
    assert!(a.tokens.expires_at.unwrap() >= before + 7_200_000.0);
}

#[tokio::test]
async fn turns_facebook_pages_into_accounts_with_page_tokens() {
    let m = mock(vec![
        route(r"oauth/access_token\?(.*)", |c| {
            if c.url.contains("fb_exchange_token") {
                ok(json!({ "access_token": "LONG" }))
            } else {
                ok(json!({ "access_token": "SHORT" }))
            }
        }),
        route(r"/me/accounts", |_| {
            ok(json!({ "data": [
                { "id": "P1", "name": "Page One", "access_token": "PT1", "picture": { "data": { "url": "https://pic/1" } }, "instagram_business_account": { "id": "IG1", "username": "pageone" } },
                { "id": "P2", "name": "Page Two", "access_token": "PT2" },
            ] }))
        }),
    ])
    .await;
    let fb = FACEBOOK.exchange(&m.http, &xp("C", "r", "v")).unwrap().await.unwrap();
    let pairs: Vec<(&str, &str)> = fb.iter().map(|a| (a.external_id.as_str(), a.tokens.access_token.as_str())).collect();
    assert_eq!(pairs, [("P1", "PT1"), ("P2", "PT2")]);
    assert_eq!(fb[0].avatar_url.as_deref(), Some("https://pic/1"));
    assert_eq!(fb[1].avatar_url, None);
    assert_eq!(m.find("/me/accounts").headers["authorization"], "Bearer LONG");
    let calls = m.matching("oauth/access_token");
    assert_eq!(
        calls[0].url,
        "https://graph.facebook.com/v23.0/oauth/access_token?client_id=facebook-id&client_secret=facebook-secret&redirect_uri=r&code=C"
    );
    assert_eq!(
        calls[1].url,
        "https://graph.facebook.com/v23.0/oauth/access_token?grant_type=fb_exchange_token&client_id=facebook-id&client_secret=facebook-secret&fb_exchange_token=SHORT"
    );
    let ig = INSTAGRAM.exchange(&m.http, &xp("C", "r", "v")).unwrap().await.unwrap();
    assert_eq!(ig.len(), 1);
    assert_eq!(ig[0].external_id, "IG1");
    assert_eq!(ig[0].display_name, "pageone");
    assert_eq!(ig[0].handle.as_deref(), Some("pageone"));
    assert_eq!(ig[0].tokens, Tokens { access_token: "PT1".into(), ..Default::default() });
    assert_eq!(ig[0].meta, Some(opts(json!({ "pageId": "P1" }))));

    let none = mock(vec![
        route(r"oauth/access_token", |_| ok(json!({ "access_token": "T" }))),
        route(r"/me/accounts", |_| ok(json!({ "data": [{ "id": "P2", "name": "Page Two", "access_token": "PT2" }] }))),
    ])
    .await;
    let e = INSTAGRAM.exchange(&none.http, &xp("C", "r", "v")).unwrap().await.unwrap_err();
    assert_eq!(e.message, "No Instagram professional account is linked to your Facebook Pages.");
    assert!(!e.transient);
    let empty = mock(vec![
        route(r"oauth/access_token", |_| ok(json!({ "access_token": "T" }))),
        route(r"/me/accounts", |_| ok(json!({}))),
    ])
    .await;
    let e = FACEBOOK.exchange(&empty.http, &xp("C", "r", "v")).unwrap().await.unwrap_err();
    assert_eq!(e.message, "No Facebook Pages found. Make sure you manage a Page and granted access to it.");
}

#[tokio::test]
async fn bluesky_connects_with_an_app_password() {
    let m = mock(vec![
        route(r"createSession", |_| ok(json!({ "did": "did:plc:abc", "handle": "acme.bsky.social", "accessJwt": "A", "refreshJwt": "R", "didDoc": { "service": [{ "id": "#atproto_pds", "type": "AtprotoPersonalDataServer", "serviceEndpoint": "https://pds.example/" }] } }))),
        route(r"getProfile", |_| ok(json!({ "displayName": "Acme", "avatar": "https://cdn/a.jpg" }))),
    ])
    .await;
    let before = oc_js::now_ms() as f64;
    let accts = BLUESKY.connect_with_password(&m.http, "@acme.bsky.social", "abcd-efgh-ijkl-mnop").unwrap().await.unwrap();
    let s = m.find("createSession");
    assert_eq!(s.url, "https://bsky.social/xrpc/com.atproto.server.createSession");
    assert_eq!(s.body, json!({ "identifier": "acme.bsky.social", "password": "abcd-efgh-ijkl-mnop" }));
    let p = m.find("getProfile");
    assert_eq!(p.url, "https://pds.example/xrpc/app.bsky.actor.getProfile?actor=did%3Aplc%3Aabc");
    assert_eq!(p.headers["authorization"], "Bearer A");
    let a = &accts[0];
    assert_eq!((a.external_id.as_str(), a.display_name.as_str()), ("did:plc:abc", "Acme"));
    assert_eq!(a.handle.as_deref(), Some("acme.bsky.social"));
    assert_eq!(a.avatar_url.as_deref(), Some("https://cdn/a.jpg"));
    let extra = a.tokens.extra.clone().unwrap();
    // The stored identifier is the one typed in (with the "@").
    assert_eq!(extra["identifier"], "@acme.bsky.social");
    assert_eq!(extra["appPassword"], "abcd-efgh-ijkl-mnop");
    assert_eq!(extra["pds"], "https://pds.example");
    assert_eq!(extra["did"], "did:plc:abc");
    assert!(a.tokens.expires_at.unwrap() >= before + 90.0 * 60_000.0);

    // A failing profile lookup falls back to the handle.
    let m = mock(vec![
        route(r"createSession", |_| ok(json!({ "did": "did:plc:x", "handle": "h.bsky.social", "accessJwt": "A", "refreshJwt": "R" }))),
        route(r"getProfile", |_| status(500, json!({}))),
    ])
    .await;
    let a = BLUESKY.connect_with_password(&m.http, "h.bsky.social", "pw").unwrap().await.unwrap();
    assert_eq!(a[0].display_name, "h.bsky.social");
    assert_eq!(a[0].avatar_url, None);
    assert_eq!(m.find("getProfile").url, "https://bsky.social/xrpc/app.bsky.actor.getProfile?actor=did%3Aplc%3Ax");
    // Wrong password: the createSession error surfaces.
    let m = mock(vec![route(r"createSession", |_| status(401, json!({ "error": "AuthenticationRequired", "message": "Invalid identifier or password" })))]).await;
    let e = BLUESKY.connect_with_password(&m.http, "h", "bad").unwrap().await.unwrap_err();
    assert_eq!(e.message, "Invalid identifier or password");
    assert!(e.reauth && !e.transient);
}

