#[test]
fn golden_http_helpers() {
    let g = golden("http.json");
    for c in g["form"].as_array().unwrap() {
        let data: Vec<(String, Option<String>)> =
            serde_json::from_value(c["data"].clone()).unwrap();
        assert_eq!(
            h::encode_form(&h::form(&data)),
            c["encoded"].as_str().unwrap()
        );
        assert_eq!(
            h::with_query("https://h.example/p", &data),
            c["withQuery"].as_str().unwrap()
        );
        assert_eq!(
            h::with_query("https://h.example/p?z=1", &data),
            c["withQueryExisting"].as_str().unwrap()
        );
    }
    for c in g["classify"].as_array().unwrap() {
        let e = h::classify(c["status"].as_u64().unwrap() as u16, "m");
        assert_eq!(
            (e.transient, e.reauth),
            (
                c["transient"].as_bool().unwrap(),
                c["reauth"].as_bool().unwrap()
            ),
            "{c}"
        );
    }
    for c in g["basic"].as_array().unwrap() {
        assert_eq!(
            h::basic(c["id"].as_str().unwrap(), c["secret"].as_str().unwrap()).1,
            c["header"].as_str().unwrap()
        );
    }
}

#[test]
fn golden_registry() {
    let g = golden("registry.json");
    let g = g.as_array().unwrap();
    assert_eq!(g.len(), ADAPTERS.len());
    for (want, a) in g.iter().zip(ADAPTERS.iter()) {
        let l = a.limits();
        let mut limits = json!({ "maxChars": l.max_chars, "images": l.images, "video": l.video, "imageTypes": l.image_types });
        if let Some(b) = l.max_image_bytes {
            limits["maxImageBytes"] = json!(b);
        }
        let got = json!({ "id": a.id(), "label": a.label(), "env": a.env(), "limits": limits, "hasRefresh": a.has_refresh() });
        assert_eq!(&got, want);
    }
}

