/// Every OAuth / app-password connect flow of the TS adapters, replayed against the same canned provider
/// responses: identical requests (method, URL, body, auth/content headers) and identical accounts.
#[tokio::test]
async fn golden_connect_flows() {
    let g = golden("connect.json");
    let env: HashMap<String, String> = serde_json::from_value(g["env"].clone()).unwrap();
    let http = Http::with_env_map(env.clone());
    for p in g["pkce"].as_array().unwrap() {
        assert_eq!(h::pkce_challenge(p["verifier"].as_str().unwrap()), p["challenge"]);
    }
    for a in g["authorize"].as_array().unwrap() {
        let p = &a["params"];
        let params = ap(p["state"].as_str().unwrap(), p["redirectUri"].as_str().unwrap(), p["codeChallenge"].as_str().unwrap());
        let got = adapter(a["adapter"].as_str().unwrap()).unwrap().authorize_url(&http, &params);
        assert_eq!(got.map(Value::from).unwrap_or(Value::Null), a["url"], "{}", a["adapter"]);
    }
    assert_eq!(Value::Array(oc_social::provider_list(&http)), g["providers"]);

    for case in g["exchange"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let routes = case["routes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| {
                let canned = r[1].clone();
                route(r[0].as_str().unwrap(), move |_| Resp {
                    status: canned.get("status").and_then(Value::as_u64).unwrap_or(200) as u16,
                    json: Some(canned["json"].clone()),
                    ..Default::default()
                })
            })
            .collect();
        let m = mock_env(routes, env.clone()).await;
        let a = adapter(case["adapter"].as_str().unwrap()).unwrap();
        let before = oc_js::now_ms() as f64;
        let res = match case["password"].as_array() {
            Some(pw) => a.connect_with_password(&m.http, pw[0].as_str().unwrap(), pw[1].as_str().unwrap()).unwrap().await,
            None => a.exchange(&m.http, &xp("C", "https://app/cb", "V")).unwrap().await,
        };
        let after = oc_js::now_ms() as f64;
        let calls = m.calls();
        let want = case["calls"].as_array().unwrap();
        assert_eq!(calls.len(), want.len(), "{name}: {calls:#?}");
        for (c, w) in calls.iter().zip(want) {
            assert_eq!(c.method, w["method"], "{name}");
            assert_eq!(c.url, w["url"], "{name}");
            assert_eq!(c.body, w["body"], "{name} {}", c.url);
            for k in ["accept", "authorization", "content-type", "user-agent"] {
                assert_eq!(c.headers.get(k).map(String::as_str), w["headers"].get(k).and_then(Value::as_str), "{name} {} {k}", c.url);
            }
        }
        match res {
            Ok(accounts) => {
                let want = case["result"]["accounts"].as_array().unwrap_or_else(|| panic!("{name}: TS failed, Rust succeeded"));
                assert_eq!(accounts.len(), want.len(), "{name}");
                for (a, w) in accounts.iter().zip(want) {
                    let mut tokens = serde_json::to_value(&a.tokens).unwrap();
                    // expiresAt is relative to Date.now() in the golden.
                    let rel = w["tokens"].get("expiresAt").and_then(Value::as_f64);
                    match (a.tokens.expires_at, rel) {
                        (Some(abs), Some(rel)) => {
                            assert!(abs >= before + rel && abs <= after + rel, "{name}: expiresAt");
                            tokens["expiresAt"] = w["tokens"]["expiresAt"].clone();
                        }
                        (None, None) => {}
                        other => panic!("{name}: expiresAt {other:?}"),
                    }
                    let mut got = Map::new();
                    got.insert("externalId".into(), json!(a.external_id));
                    got.insert("displayName".into(), json!(a.display_name));
                    if let Some(x) = &a.handle {
                        got.insert("handle".into(), json!(x));
                    }
                    if let Some(x) = &a.avatar_url {
                        got.insert("avatarUrl".into(), json!(x));
                    }
                    got.insert("tokens".into(), tokens);
                    if let Some(x) = &a.meta {
                        got.insert("meta".into(), Value::Object(x.clone()));
                    }
                    assert_eq!(Value::Object(got), *w, "{name}");
                }
            }
            Err(e) => {
                let w = &case["result"]["error"];
                assert!(w.is_object(), "{name}: Rust failed with {e:?}");
                assert_eq!(e.message, w["message"], "{name}");
                assert_eq!(e.transient, w["transient"].as_bool().unwrap_or(false), "{name}");
                assert_eq!(e.status.map(Value::from).unwrap_or(Value::Null), w["status"], "{name}");
                assert_eq!(e.reauth, w["reauth"].as_bool().unwrap_or(false), "{name}");
            }
        }
    }
}
